using System;using System.Collections.Generic;using System.Configuration;using System.Data.SqlClient;using System.Web;using System.Web.Services;using System.Web.UI;namespace Mathling{    public partial class Forum : Page    {        protected void Page_Load(object sender, EventArgs e)        {        }        public class ThreadDto        {            public string id { get; set; }            public string title { get; set; }            public string content { get; set; }            public string category { get; set; }            public string author { get; set; }            public string authorId { get; set; }            public string role { get; set; }            public string avatar { get; set; }            public int replies { get; set; }            public string date { get; set; }            public List<ReplyDto> replyList { get; set; }        }        public class ReplyDto        {            public string id { get; set; }            public string author { get; set; }            public string authorId { get; set; }            public string role { get; set; }            public string avatar { get; set; }            public string content { get; set; }            public string date { get; set; }        }        [WebMethod]        public static List<ThreadDto> GetThreads()        {            var threads = new List<ThreadDto>();            string connStr = ConfigurationManager.ConnectionStrings["MathlingDB"].ConnectionString;            using (SqlConnection conn = new SqlConnection(connStr))            {                conn.Open();                string query = @"                    SELECT                         t.Id, t.Title, t.Category, t.CreatedAt, t.AuthorId,                        u.Name as AuthorName, u.Role as AuthorRole, u.Avatar,                        (SELECT COUNT(*) FROM ForumReplies r WHERE r.ThreadId = t.Id) as ReplyCount                    FROM ForumThreads t                    JOIN Users u ON t.AuthorId = TRY_CAST(u.Id AS INT)                    ORDER BY t.CreatedAt DESC";                using (SqlCommand cmd = new SqlCommand(query, conn))                using (SqlDataReader reader = cmd.ExecuteReader())                {                    while (reader.Read())                    {                        threads.Add(new ThreadDto                        {                            id = reader["Id"].ToString(),                            title = reader["Title"].ToString(),                            category = reader["Category"].ToString(),                            author = reader["AuthorName"].ToString(),                            authorId = reader["AuthorId"].ToString(),                            role = reader["AuthorRole"].ToString(),                            avatar = reader["Avatar"].ToString(),                            replies = Convert.ToInt32(reader["ReplyCount"]),                            date = Convert.ToDateTime(reader["CreatedAt"]).ToString("yyyy-MM-dd")                        });                    }                }            }            return threads;        }        [WebMethod]        public static ThreadDto GetThread(string threadId)        {            ThreadDto thread = null;            try            {                string connStr = ConfigurationManager.ConnectionStrings["MathlingDB"].ConnectionString;                using (SqlConnection conn = new SqlConnection(connStr))                {                    conn.Open();                    string threadQuery = @"                        SELECT                             t.Id, t.Title, t.Content, t.Category, t.CreatedAt, t.AuthorId,                            u.Name as AuthorName, u.Role as AuthorRole, u.Avatar                        FROM ForumThreads t                        JOIN Users u ON t.AuthorId = TRY_CAST(u.Id AS INT)                        WHERE t.Id = @Id";                    using (SqlCommand cmd = new SqlCommand(threadQuery, conn))                    {                        cmd.Parameters.AddWithValue("@Id", threadId);                        using (SqlDataReader reader = cmd.ExecuteReader())                        {                            if (reader.Read())                            {                                thread = new ThreadDto                                {                                    id = reader["Id"].ToString(),                                    title = reader["Title"].ToString(),                                    content = reader["Content"].ToString(),                                    category = reader["Category"].ToString(),                                    author = reader["AuthorName"].ToString(),                                    authorId = reader["AuthorId"].ToString(),                                    role = reader["AuthorRole"].ToString(),                                    avatar = reader["Avatar"].ToString(),                                    date = Convert.ToDateTime(reader["CreatedAt"]).ToString("yyyy-MM-dd"),                                    replyList = new List<ReplyDto>()                                };                            }                        }                    }                    if (thread != null)                    {                        string replyQuery = @"                            SELECT                                 r.Id, r.Content, r.CreatedAt, r.AuthorId,                                u.Name as AuthorName, u.Role as AuthorRole, u.Avatar                            FROM ForumReplies r                            JOIN Users u ON r.AuthorId = TRY_CAST(u.Id AS INT)                            WHERE r.ThreadId = @ThreadId                            ORDER BY r.CreatedAt ASC";                        using (SqlCommand rCmd = new SqlCommand(replyQuery, conn))                        {                            rCmd.Parameters.AddWithValue("@ThreadId", threadId);                            using (SqlDataReader rReader = rCmd.ExecuteReader())                            {                                while (rReader.Read())                                {                                    thread.replyList.Add(new ReplyDto                                    {                                        id = rReader["Id"].ToString(),                                        author = rReader["AuthorName"].ToString(),                                        authorId = rReader["AuthorId"].ToString(),                                        role = rReader["AuthorRole"].ToString(),                                        avatar = rReader["Avatar"].ToString(),                                        content = rReader["Content"].ToString(),                                        date = Convert.ToDateTime(rReader["CreatedAt"]).ToString("yyyy-MM-dd")                                    });                                }                            }                        }                        thread.replies = thread.replyList.Count;                    }                }            }            catch (Exception ex)            {                return new ThreadDto { title = "Error", content = ex.Message, id = threadId, replyList = new List<ReplyDto>() };            }            return thread;        }        [WebMethod(EnableSession = true)]        public static string CreateThread(string title, string content, string category)        {            if (HttpContext.Current.Session["UserId"] == null)                return "error|Not logged in";            string userId = HttpContext.Current.Session["UserId"].ToString();            string connStr = ConfigurationManager.ConnectionStrings["MathlingDB"].ConnectionString;            using (SqlConnection conn = new SqlConnection(connStr))            {                conn.Open();                string newId = Guid.NewGuid().ToString().Substring(0, 8);                string query = @"                    INSERT INTO ForumThreads (Id, Title, Content, Category, AuthorId, CreatedAt)                    VALUES (@Id, @Title, @Content, @Category, @AuthorId, GETDATE())";                using (SqlCommand cmd = new SqlCommand(query, conn))                {                    cmd.Parameters.AddWithValue("@Id", newId);                    cmd.Parameters.AddWithValue("@Title", title);                    cmd.Parameters.AddWithValue("@Content", content);                    cmd.Parameters.AddWithValue("@Category", category);                    cmd.Parameters.AddWithValue("@AuthorId", userId);                    cmd.ExecuteNonQuery();                }            }            return "success";        }        [WebMethod(EnableSession = true)]        public static string AddReply(string threadId, string content)        {            if (HttpContext.Current.Session["UserId"] == null)                return "error|Not logged in";            string userId = HttpContext.Current.Session["UserId"].ToString();            string connStr = ConfigurationManager.ConnectionStrings["MathlingDB"].ConnectionString;            using (SqlConnection conn = new SqlConnection(connStr))            {                conn.Open();                string newId = Guid.NewGuid().ToString().Substring(0, 8);                string query = @"                    INSERT INTO ForumReplies (Id, ThreadId, Content, AuthorId, CreatedAt)                    VALUES (@Id, @ThreadId, @Content, @AuthorId, GETDATE())";                using (SqlCommand cmd = new SqlCommand(query, conn))                {                    cmd.Parameters.AddWithValue("@Id", newId);                    cmd.Parameters.AddWithValue("@ThreadId", threadId);                    cmd.Parameters.AddWithValue("@Content", content);                    cmd.Parameters.AddWithValue("@AuthorId", userId);                    cmd.ExecuteNonQuery();                }            }            return "success";        }        [WebMethod(EnableSession = true)]        public static string DeleteThread(string threadId)        {            if (HttpContext.Current.Session["UserId"] == null)                return "error|Not logged in";            string userId = HttpContext.Current.Session["UserId"].ToString();            string role = HttpContext.Current.Session["UserRole"]?.ToString() ?? "";            string connStr = ConfigurationManager.ConnectionStrings["MathlingDB"].ConnectionString;            using (SqlConnection conn = new SqlConnection(connStr))            {                conn.Open();                if (role != "admin")                {                    string checkQuery = "SELECT AuthorId FROM ForumThreads WHERE Id = @Id";                    using (SqlCommand cmd = new SqlCommand(checkQuery, conn))                    {                        cmd.Parameters.AddWithValue("@Id", threadId);                        object authorId = cmd.ExecuteScalar();                        if (authorId == null) return "error|Thread not found";                        if (authorId.ToString() != userId) return "error|Unauthorized";                    }                }                string delReplies = "DELETE FROM ForumReplies WHERE ThreadId = @Id";                using (SqlCommand cmd = new SqlCommand(delReplies, conn))                {                    cmd.Parameters.AddWithValue("@Id", threadId);                    cmd.ExecuteNonQuery();                }                string delThread = "DELETE FROM ForumThreads WHERE Id = @Id";                using (SqlCommand cmd = new SqlCommand(delThread, conn))                {                    cmd.Parameters.AddWithValue("@Id", threadId);                    cmd.ExecuteNonQuery();                }            }            return "success";        }        [WebMethod(EnableSession = true)]        public static string DeleteReply(string replyId)        {            if (HttpContext.Current.Session["UserId"] == null)                return "error|Not logged in";            string userId = HttpContext.Current.Session["UserId"].ToString();            string role = HttpContext.Current.Session["UserRole"]?.ToString() ?? "";            string connStr = ConfigurationManager.ConnectionStrings["MathlingDB"].ConnectionString;            using (SqlConnection conn = new SqlConnection(connStr))            {                conn.Open();                if (role != "admin")                {                    string checkQuery = "SELECT AuthorId FROM ForumReplies WHERE Id = @Id";                    using (SqlCommand cmd = new SqlCommand(checkQuery, conn))                    {                        cmd.Parameters.AddWithValue("@Id", replyId);                        object authorId = cmd.ExecuteScalar();                        if (authorId == null) return "error|Reply not found";                        if (authorId.ToString() != userId) return "error|Unauthorized";                    }                }                string delReply = "DELETE FROM ForumReplies WHERE Id = @Id";                using (SqlCommand cmd = new SqlCommand(delReply, conn))                {                    cmd.Parameters.AddWithValue("@Id", replyId);                    cmd.ExecuteNonQuery();                }            }            return "success";        }    }}